async function(PIXI, app, api) {
  // This is the visual model's response for the supplied circuit, not a renderer template.
  const root = new PIXI.Container(); app.stage.addChild(root);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 920 560">
    <defs>
      <linearGradient id="wood" x2="0" y2="1"><stop stop-color="#e9dcc5"/><stop offset="1" stop-color="#c9bba2"/></linearGradient>
      <linearGradient id="board" x2="0" y2="1"><stop stop-color="#fcfbf7"/><stop offset="1" stop-color="#e2e6e5"/></linearGradient>
      <linearGradient id="metal" x2="0" y2="1"><stop stop-color="#f7fafc"/><stop offset=".45" stop-color="#a9b5bf"/><stop offset=".7" stop-color="#dce4e8"/><stop offset="1" stop-color="#748591"/></linearGradient>
      <linearGradient id="ceramic" x2="0" y2="1"><stop stop-color="#fff6dd"/><stop offset=".55" stop-color="#ebce95"/><stop offset="1" stop-color="#bc985f"/></linearGradient>
      <linearGradient id="source" x2="0" y2="1"><stop stop-color="#314d61"/><stop offset="1" stop-color="#152b3d"/></linearGradient>
    </defs>
    <rect width="920" height="560" fill="url(#wood)"/>
    <path d="M0 44H920M0 521H920" stroke="#b9a889" stroke-width="2" opacity=".3"/>
    <rect x="38" y="44" width="854" height="477" rx="22" fill="#897d6d" opacity=".25"/>
    <rect x="30" y="34" width="854" height="477" rx="22" fill="url(#board)" stroke="#c0c8c6" stroke-width="2"/>
    <g fill="#a4afb3" stroke="#71818a" stroke-width="1.5">
      <circle cx="53" cy="57" r="7"/><circle cx="861" cy="57" r="7"/><circle cx="53" cy="488" r="7"/><circle cx="861" cy="488" r="7"/>
    </g>
    <path d="M49 57H57M857 57H865M49 488H57M857 488H865" stroke="#65747c" stroke-width="2"/>
    <text x="71" y="81" fill="#243d50" font-family="Arial" font-size="28" font-weight="bold">Một mạch — hai nhánh</text>
    <text x="71" y="108" fill="#607582" font-family="Arial" font-size="17">R₁ nối tiếp với R₂ ∥ R₃</text>
    <!-- Wires follow the confirmed topology; the intermediate solver units are not apparatus. -->
    <path d="M180 225V150H550V250H830V440H180V365M550 250V370H830" fill="none" stroke="#9b8e79" stroke-width="11" stroke-linejoin="round" opacity=".2" transform="translate(0 4)"/>
    <path d="M180 225V150H550V250H830V440H180V365M550 250V370H830" fill="none" stroke="#374c5c" stroke-width="6" stroke-linejoin="round"/>
    <!-- Bench supply and terminals. -->
    <rect x="134" y="238" width="100" height="133" rx="12" fill="#85939b" opacity=".2"/>
    <rect x="128" y="230" width="100" height="133" rx="12" fill="url(#source)" stroke="#0e2435" stroke-width="2"/>
    <rect x="142" y="247" width="72" height="37" rx="5" fill="#e7f3ee"/>
    <text x="178" y="273" text-anchor="middle" font-family="Arial" font-size="21" font-weight="bold" fill="#255349">DC</text>
    <circle cx="151" cy="318" r="10" fill="url(#metal)"/><path d="M151 310V316" stroke="#324554" stroke-width="2"/>
    <circle cx="180" cy="225" r="9" fill="#dc7255" stroke="#893e32" stroke-width="2"/>
    <circle cx="180" cy="365" r="9" fill="#7895a5" stroke="#3c596c" stroke-width="2"/>
    <text x="154" y="223" font-family="Arial" font-size="20" fill="#a23f2e">+</text>
    <text x="154" y="374" font-family="Arial" font-size="20" fill="#3c596c">−</text>
    <!-- Ceramic resistors, collars and wire terminals. -->
    <g>
      <rect x="351" y="132" width="128" height="42" rx="11" fill="#8b7e67" opacity=".2"/>
      <rect x="348" y="128" width="128" height="42" rx="11" fill="url(#ceramic)" stroke="#9a7a4c" stroke-width="2"/>
      <rect x="348" y="128" width="11" height="42" rx="4" fill="url(#metal)"/><rect x="465" y="128" width="11" height="42" rx="4" fill="url(#metal)"/>
      <path d="M382 131V167M419 131V167" stroke="#af7d38" stroke-width="5" opacity=".65"/>
      <rect x="644" y="232" width="108" height="42" rx="11" fill="#8b7e67" opacity=".2"/>
      <rect x="640" y="228" width="108" height="42" rx="11" fill="url(#ceramic)" stroke="#9a7a4c" stroke-width="2"/>
      <rect x="640" y="228" width="11" height="42" rx="4" fill="url(#metal)"/><rect x="737" y="228" width="11" height="42" rx="4" fill="url(#metal)"/>
      <path d="M670 231V267M701 231V267" stroke="#855b43" stroke-width="5" opacity=".7"/>
      <rect x="644" y="352" width="108" height="42" rx="11" fill="#8b7e67" opacity=".2"/>
      <rect x="640" y="348" width="108" height="42" rx="11" fill="url(#ceramic)" stroke="#9a7a4c" stroke-width="2"/>
      <rect x="640" y="348" width="11" height="42" rx="4" fill="url(#metal)"/><rect x="737" y="348" width="11" height="42" rx="4" fill="url(#metal)"/>
      <path d="M670 351V387M701 351V387" stroke="#c47a43" stroke-width="5" opacity=".7"/>
    </g>
    <g fill="#d9a74c" stroke="#8c6b38" stroke-width="2"><circle cx="550" cy="250" r="7"/><circle cx="830" cy="250" r="7"/><circle cx="830" cy="370" r="7"/></g>
    <path d="M602 242L613 250L602 258" fill="none" stroke="#3478a1" stroke-width="3"/>
    <path d="M602 362L613 370L602 378" fill="none" stroke="#aa6540" stroke-width="3"/>
    <path d="M795 433L784 440L795 447" fill="none" stroke="#147a79" stroke-width="3"/>
    <rect x="276" y="270" width="223" height="93" rx="12" fill="#e9efef" stroke="#ccd7d8"/>
    <text x="293" y="295" font-family="Arial" font-size="17" fill="#56707e">Điện áp trên hai nhánh</text>
    <text x="71" y="480" font-family="Arial" font-size="17" fill="#607582">Chấm sáng minh họa chiều và tỉ lệ dòng điện; không phải tốc độ electron.</text>
  </svg>`;
  const texture = await api.svgTexture(svg);
  const art = new PIXI.Sprite(texture); root.addChild(art);
  const labels = {};
  function text(key,x,y,size=23,color='#243d50',center=false) {
    const item = new PIXI.Text({text:'',style:{fontFamily:'Arial',fontSize:size,fill:color,fontWeight:'600'}});
    if (center) item.anchor.set(.5,0); item.position.set(x,y); root.addChild(item); labels[key]=item;
  }
  text('E',177,385,23,'#243d50',true);
  text('R1',412,180,21,'#243d50',true);
  text('R2',694,194,21,'#243d50',true);
  text('R3',694,314,21,'#243d50',true);
  text('r',181,307,17,'#d5e3ea');
  text('I',360,214,25,'#147a79',true);
  text('I2',694,286,24,'#3478a1',true);
  text('I3',694,406,24,'#aa6540',true);
  text('U',293,312,28,'#147a79');
  const tracks = [
    {key:'src.current',points:[[180,225],[180,150],[550,150],[550,250]],n:6},
    {key:'par.current_1',points:[[550,250],[830,250],[830,370]],n:5,color:'#3478a1'},
    {key:'par.current_2',points:[[550,250],[550,370],[830,370]],n:5,color:'#aa6540'},
    {key:'src.current',points:[[830,370],[830,440],[180,440],[180,365]],n:10},
  ];
  for (const track of tracks) {
    track.lengths=track.points.slice(1).map((p,i)=>Math.hypot(p[0]-track.points[i][0],p[1]-track.points[i][1]));
    track.total=track.lengths.reduce((a,b)=>a+b,0);
    track.dots=Array.from({length:track.n},()=>{const g=new PIXI.Graphics().circle(0,0,5).fill({color:track.color||'#22b8ac'});root.addChild(g);return g;});
  }
  function fit() {
    const k=Math.min(api.width/920,api.height/560); root.scale.set(k);
    root.position.set((api.width-920*k)/2,(api.height-560*k)/2);
  }
  const num=(value,digits=3)=>Number(value).toFixed(digits);
  fit();
  return {update(frame) {
    fit(); const f=frame.fields,p=frame.parameters;
    labels.E.text='E = '+num(p.emf,1)+' V';
    labels.R1.text='R₁ · '+num(p.R1,1)+' Ω';
    labels.R2.text='R₂ · '+num(p.R2,1)+' Ω';
    labels.R3.text='R₃ · '+num(p.R3,1)+' Ω';
    labels.r.text='r = '+num(p.r_internal,1)+' Ω';
    labels.I.text='I = '+num(f['src.current'])+' A';
    labels.I2.text='I₂ = '+num(f['par.current_1'])+' A';
    labels.I3.text='I₃ = '+num(f['par.current_2'])+' A';
    labels.U.text='U = '+num(f['split.voltage_2'],2)+' V';
    for (const track of tracks) {
      const current=f[track.key];
      for (let i=0;i<track.n;i++) {
        const dot=track.dots[i]; dot.visible=Math.abs(current)>1e-10;
        let distance=((frame.t*current*85+i*track.total/track.n)%track.total+track.total)%track.total;
        let segment=0;
        while(segment<track.lengths.length-1 && distance>track.lengths[segment]) {distance-=track.lengths[segment];segment++;}
        const u=distance/track.lengths[segment],a=track.points[segment],b=track.points[segment+1];
        dot.position.set(a[0]+u*(b[0]-a[0]),a[1]+u*(b[1]-a[1]));
      }
    }
  },resize:fit,setData:fit,destroy(){root.destroy({children:true});api.releaseTexture(texture);}};
}
